// Кейс: .qa/tests/children/CHD-005.md · план: .qa/e2e-app/specs/app.md (1.6)
// Метки «לעדכן פרטים» в «ילדים», баннер на «בית» (X = числу меток), тап → «ילדים», в карточке «בדיקה תקופתית / אושר לאחרונה / הפרטים עדיין נכונים».
// «הפרטים עדיין נכונים» НЕ нажимается (сбросит просрочку — вернуть может только программист). Только просмотр.
import { by, assert } from '../../lib/appium.mjs';
import { onHome, openTab } from '../../lib/banci.mjs';

export const name = 'תזכורת תקופתית: «לעדכן פרטים» в ילדים, баннер «X כרטיסים מחכים לעדכון» на בית → ילדים → карточка «בדיקה תקופתית» #5ffe7018 @iphone @app @prod-safe';

const TAG = 'לעדכן פרטים';
const BANNER = '(name CONTAINS "מחכים לעדכון" OR label CONTAINS "מחכים לעדכון" OR name CONTAINS "מחכה לעדכון" OR label CONTAINS "מחכה לעדכון")';
const NUM = { 'כרטיס אחד': 1, 'שני כרטיסים': 2, 'שלושה כרטיסים': 3, 'ארבעה כרטיסים': 4 };

function bannerCount(text) {
  const t = String(text);
  const d = t.match(/(\d+)\s*כרטיסים/);
  if (d) return +d[1];
  for (const [w, n] of Object.entries(NUM)) if (t.includes(w)) return n;
  return null;
}

export default async function (app) {
  // 1. «ילדים»: метки «לעדכן פרטים».
  await onHome(app);
  await openTab(app, 'ילדים');
  await app.waitFor(by.contains(TAG), { timeout: 20000, what: `ПРЕДУСЛОВИЕ: в «ילדים» есть метка «${TAG}» (карточки не подтверждались > 90 дней; если нажали «הפרטים עדיין נכונים» — данные готовит программист)` });
  let tags = await app.findAll(by.contains(TAG, 'StaticText'));
  if (!tags.length) tags = await app.findAll(by.exact(TAG));
  const tagCount = tags.length;
  assert(tagCount >= 1, `в «ילדים» есть «${TAG}»`);

  // 2. «בית»: баннер «X כרטיסים מחכים לעדכון» + подзаголовок.
  await openTab(app, 'בית');
  const banner = await app.scrollTo(BANNER, { max: 4, what: 'баннер «X כרטיסים מחכים לעדכון» на «בית»' });
  assert(await app.exists(by.contains('בדקו שהפרטים והתמונה עדיין נכונים')), 'подзаголовок «בדקו שהפרטים והתמונה עדיין נכונים»');
  const bText = `${await banner.attr('label') ?? ''} ${await banner.attr('name') ?? ''}`;
  const x = bannerCount(bText);
  assert(x !== null, `в баннере есть число карточек («${bText.trim()}»)`);
  assert(x === tagCount, `число в баннере (${x}) = числу меток «${TAG}» в «ילדים» (${tagCount})`);

  // 3. Тап по баннеру → «ילדים» (AC3).
  await banner.click();
  const tagged = await app.waitFor(by.contains(TAG), { timeout: 15000, what: 'после тапа по баннеру — «ילדים» с метками' });

  // 4. Карточка ребёнка с меткой: блок «בדיקה תקופתית».
  await tagged.click();
  await app.waitFor(by.contains('בדיקה תקופתית'), { timeout: 15000, what: 'блок «בדיקה תקופתית» в карточке ребёнка' });
  const last = await app.waitFor(by.contains('אושר לאחרונה'), { what: '«אושר לאחרונה: <дата>»' });
  const lastText = String(await last.attr('label') ?? await last.attr('name'));
  assert(/\d{1,2}[./]\d{1,2}[./]\d{4}/.test(lastText), `«אושר לאחרונה» с датой («${lastText}»)`);
  assert(await app.exists(by.contains('הפרטים עדיין נכונים')), 'ссылка «הפרטים עדיין נכונים» есть (НЕ нажимаем)');

  // 5. Выход без изменений (не «שמירה», не «הפרטים עדיין נכונים»).
  await app.restart();
}
